package com.smartseating.ui;

import com.smartseating.dao.*;
import com.smartseating.model.*;
import com.smartseating.service.*;
import com.smartseating.util.*;
import javax.swing.*;
import java.awt.*;
import java.util.List;
import java.util.Map;
import java.util.LinkedHashMap;
import java.util.stream.Collectors;

public class SeatingResultFrame extends AppFrame {
    private final ExamService.GenerationSummary summary;private final SeatingDAO seatingDAO=new SeatingDAO();private final InvigilatorDAO invigilatorDAO=new InvigilatorDAO();private final JTextArea output=new JTextArea();
    public SeatingResultFrame(User user,ExamService.GenerationSummary summary){super("Seating Arrangement Result",user);this.summary=summary;UI.frame(this,1100,760);build();showArrangement();}
    private void build(){content.add(title("Seating Arrangement • "+summary.exam().getName()),BorderLayout.NORTH);output.setFont(new Font("Monospaced",Font.PLAIN,12));output.setEditable(false);output.setMargin(new Insets(14,14,14,14));content.add(white(UI.scroll(output)),BorderLayout.CENTER);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT,7,0));buttons.setOpaque(false);JButton print=button("PRINT",UI.BLUE),chart=button("PRINT ROOM CHART",UI.TEAL),attendance=button("PRINT ATTENDANCE",UI.ORANGE),duty=button("PRINT INVIGILATOR LIST",new Color(120,100,175)),complete=button("PRINT COMPLETE REPORT",new Color(70,130,100)),back=button("BACK",UI.MUTED);buttons.add(print);buttons.add(chart);buttons.add(attendance);buttons.add(duty);buttons.add(complete);buttons.add(back);content.add(buttons,BorderLayout.SOUTH);print.addActionListener(e->PrintService.print("Seating Arrangement",arrangement()));chart.addActionListener(e->PrintService.print("Room Seating Chart",roomChart()));attendance.addActionListener(e->PrintService.print("Attendance Sheet",attendanceReport()));duty.addActionListener(e->PrintService.print("Invigilator Duty List",dutyReport()));complete.addActionListener(e->PrintService.print("Complete Examination Report",completeReport()));back.addActionListener(e->dispose());}
    private void showArrangement(){output.setText(arrangement());output.setCaretPosition(0);}
    private String header(String title){Exam e=summary.exam();return "SMART EXAM SEATING ARRANGEMENT SYSTEM\n================================================\n"+title+"\nExam: "+e.getName()+"\nType: "+e.getType()+"\nDate: "+DateUtil.examDate(e)+"    Time: "+DateUtil.examTime(e)+"\nSubject: "+e.getSubject()+"\nShuffle: "+summary.shuffle()+"\n\n";}
    private List<Seating> seats(){try{return seatingDAO.findByExam(summary.exam().getId());}catch(Exception ex){error(ex);return List.of();}}
    private String arrangement(){StringBuilder b=new StringBuilder(header("SEATING ARRANGEMENT"));Map<String,List<Seating>> byRoom=seats().stream().collect(Collectors.groupingBy(Seating::getRoomNumber,LinkedHashMap::new,Collectors.toList()));for(Map.Entry<String,List<Seating>> e:byRoom.entrySet()){b.append("ROOM: ").append(e.getKey()).append("\nSeat       Register No        Name                    Dept\n");for(Seating s:e.getValue())b.append(String.format("%-10s %-18s %-23s %s%n",s.getSeatNumber(),s.getRegisterNumber(),s.getStudentName(),s.getDepartmentCode()));b.append("Invigilator: ").append(e.getValue().isEmpty()?"Unassigned":e.getValue().get(0).getInvigilatorName()).append("\n\n");}b.append("Students: ").append(summary.students().size()).append("\nCapacity: ").append(summary.capacity()).append("\nEmpty Seats: ").append(summary.emptySeats()).append("\n");return b.toString();}
    private String roomChart(){StringBuilder b=new StringBuilder(header("ROOM-WISE SEATING CHART"));for(Room room:summary.rooms()){b.append("ROOM ").append(room.getRoomNumber()).append("   Capacity: ").append(room.getCapacity()).append("   Students: ").append(seats().stream().filter(s->s.getRoomNumber().equals(room.getRoomNumber())).count()).append("\nBLACKBOARD\n     ");for(int c=1;c<=room.getColumns();c++)b.append(String.format("%-13s",c));b.append("\n");List<Seating> roomSeats=seats().stream().filter(s->s.getRoomNumber().equals(room.getRoomNumber())).toList();for(int r=0;r<room.getRows();r++){String label=String.valueOf((char)('A'+r));b.append(String.format("%-5s",label));for(int c=1;c<=room.getColumns();c++){final int col=c;String value=roomSeats.stream().filter(s->s.getRowLabel().equals(label)&&s.getColumnNumber()==col).map(Seating::getRegisterNumber).findFirst().orElse("EMPTY");b.append(String.format("%-13s",value));}b.append("\n");}String inv=roomSeats.isEmpty()?"Unassigned":roomSeats.get(0).getInvigilatorName();b.append("Invigilator: ").append(inv).append("\n\n");}return b.toString();}
    private String attendanceReport(){StringBuilder b=new StringBuilder(header("ATTENDANCE SHEET"));for(Room room:summary.rooms()){b.append("ROOM: ").append(room.getRoomNumber()).append("\nInvigilator: ");List<Seating> list=seats().stream().filter(s->s.getRoomNumber().equals(room.getRoomNumber())).toList();b.append(list.isEmpty()?"Unassigned":list.get(0).getInvigilatorName()).append("\n\nSl No | Register No       | Name                         | Signature\n");int i=1;for(Seating s:list)b.append(String.format("%-6d| %-18s| %-29s| ____________________%n",i++,s.getRegisterNumber(),s.getStudentName()));b.append("Total Students: ").append(list.size()).append("\nInvigilator Signature: ____________________\n\n");}return b.toString();}
    private String dutyReport(){StringBuilder b=new StringBuilder(header("INVIGILATOR DUTY LIST"));b.append("Room       Teacher                         Designation\n");try{for(String[] row:invigilatorDAO.findByExam(summary.exam().getId()))b.append(String.format("%-10s %-31s %s%n",row[0],row[1],row[2]));}catch(Exception ex){b.append(ex.getMessage());}return b.toString();}
    private String completeReport(){return header("COMPLETE EXAMINATION REPORT")+"Departments: "+summary.students().stream().map(Student::getDepartmentCode).distinct().sorted().collect(Collectors.joining(", "))+"\nSemesters: "+summary.students().stream().map(Student::getSemesterNumber).distinct().sorted().collect(Collectors.joining(", "))+"\nStudents: "+summary.students().size()+"\nRooms used: "+summary.rooms().stream().map(Room::getRoomNumber).collect(Collectors.joining(", "))+"\nCapacity: "+summary.capacity()+"\nEmpty seats: "+summary.emptySeats()+"\nShuffle method: "+summary.shuffle()+"\n\n"+dutyReport();}
}
